HTML = "<!doctype html>\n<html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\"><title>EduChain | Credential evidence lab</title>\n<style>\n:root{color-scheme:light;--bg:#f5f7fa;--ink:#142235;--muted:#526175;--border:#dce4ed;--accent:#175f63}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.6 system-ui,sans-serif}main{max-width:1120px;margin:auto;padding:32px 24px 60px}header{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid var(--border);padding:12px 0 24px}a{color:var(--accent)}.brand{font-size:24px;font-weight:750;letter-spacing:-.8px}.eyebrow{font-size:12px;text-transform:uppercase;letter-spacing:1.5px;color:var(--accent);font-weight:700}h1{font-size:clamp(30px,5vw,50px);line-height:1.12;letter-spacing:-1.8px;margin:12px 0}h2{font-size:18px;margin:0 0 12px}p{margin:8px 0;color:var(--muted)}.hero{padding:44px 0 24px;max-width:780px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.panel{background:#fff;border:1px solid var(--border);border-radius:16px;padding:22px;min-width:0}.full{grid-column:1/-1}label{font-weight:650;display:block;margin:12px 0 6px}select,button,input{font:inherit;border:1px solid var(--border);border-radius:9px;padding:10px;background:white;color:var(--ink);max-width:100%}select{width:100%}button{background:var(--accent);color:white;border:0;cursor:pointer;font-weight:650;margin-top:14px}button:disabled{opacity:.5}.status{font-size:28px;font-weight:750;margin:8px 0}.score{font-size:24px;font-weight:700}.pill{font-size:12px;padding:4px 10px;border-radius:999px;background:#e7eeef;color:#175f63;display:inline-block}.row{display:flex;justify-content:space-between;gap:12px;align-items:center;border-bottom:1px solid var(--border);padding:10px 0;overflow-wrap:anywhere}.row:last-child{border:none}.small{font-size:12px;color:var(--muted)}.mono{font:12px/1.7 ui-monospace,monospace;overflow-wrap:anywhere}.warn{padding:12px;border:1px solid #e4d6a9;background:#fffbef;border-radius:10px;color:#694f13}footer{margin-top:28px;color:var(--muted);font-size:13px}@media(max-width:700px){.grid{grid-template-columns:1fr}main{padding:18px 14px 40px}header{align-items:flex-start;gap:8px}}\n</style></head><body><main><header><div class=\"brand\">EduChain</div><nav><a href=\"/docs\">API documentation</a> &nbsp; <a href=\"https://github.com/ruthvikreddyv/educhain\">Source code</a></nav></header>\n<section class=\"hero\"><div class=\"eyebrow\">Credential verification research</div><h1>Evidence, not assumptions.</h1><p>Explore provenance-aware credential reasoning, counterfactual evidence interventions and adaptive verification actions.</p><p class=\"warn\">Research demonstration using synthetic evidence only. No genuine credential is authenticated, issued or uploaded here.</p></section>\n<div class=\"grid\"><section class=\"panel\"><h2>Verification scenario</h2><label for=\"scenario\">Select a synthetic case</label><select id=\"scenario\"><option value=\"genuine\">Complete evidence</option><option value=\"missing\">Missing issuer evidence</option><option value=\"duplicate\">Correlated evidence</option><option value=\"conflict\">Conflicting evidence</option><option value=\"issuer_fraud\">Issuer-record inconsistency</option><option value=\"revoked\">Revocation</option></select><button id=\"run\">Run verification</button><p id=\"description\"></p><p id=\"error\" role=\"alert\"></p></section>\n<section class=\"panel\" aria-live=\"polite\"><h2>Verification outcome</h2><div id=\"status\" class=\"status\">Not evaluated</div><div class=\"row\"><span>Provenance-aware score</span><span id=\"score\" class=\"score\">—</span></div><div class=\"row\"><span>Independent-evidence baseline</span><span id=\"baseline\">—</span></div><div class=\"row\"><span>Independent source groups</span><span id=\"components\">—</span></div><p id=\"details\" class=\"small\">Scores are heuristic, not probabilities of authenticity.</p></section>\n<section class=\"panel full\"><h2>Evidence ledger</h2><div id=\"evidence\"><p>Run a scenario to inspect evidence.</p></div></section>\n<section class=\"panel\"><h2>Counterfactual interventions</h2><p class=\"small\">Minimum explicit evidence removals within the bounded search; dependent observations are removed too.</p><div id=\"cf\"></div></section>\n<section class=\"panel\"><h2>Recommended next check</h2><div id=\"action\"></div><p class=\"small\">Action selection uses illustrative outcome probabilities and declared costs.</p></section>\n<section class=\"panel full\"><h2>Private document hash</h2><p>Calculate SHA-256 locally in your browser. The document is not sent to any server. A hash alone does not prove authenticity.</p><label for=\"file\">Choose a file</label><input id=\"file\" type=\"file\"><p id=\"digest\" class=\"mono\" aria-live=\"polite\"></p></section>\n</div><footer>EduChain v2 · Synthetic research prototype · <a href=\"/health\">Backend health</a></footer></main>\n<script>\nconst $=id=>document.getElementById(id);\nfunction line(parent,a,b){const row=document.createElement('div');row.className='row';const left=document.createElement('span');left.textContent=a;const right=document.createElement('span');right.textContent=b;row.append(left,right);parent.append(row)}\nasync function run(){const btn=$('run');btn.disabled=true;$('error').textContent='';try{const r=await fetch('/demo/'+encodeURIComponent($('scenario').value));if(!r.ok)throw Error('Backend unavailable');const d=await r.json();$('description').textContent=d.description;$('status').textContent=d.decision.state;$('score').textContent=d.decision.score.toFixed(3);$('baseline').textContent=d.independent.score.toFixed(3);$('components').textContent=d.decision.components;$('details').textContent='Missing: '+(d.decision.missing.join(', ')||'none')+' | Conflicts: '+(d.decision.conflicts.join(', ')||'none')+' | Heuristic score only.';$('evidence').replaceChildren();for(const e of d.evidence)line($('evidence'),e.claim+' · '+e.source,(e.polarity===1?'Supports':'Contradicts')+' · '+(e.authenticated?'Synthetic authenticated':'Untrusted')+' · '+e.reliability.toFixed(2));$('cf').replaceChildren();for(const c of d.counterfactual.interventions)line($('cf'),c.removed.join(', '),c.state);if(!d.counterfactual.interventions.length)$('cf').textContent='No decision-changing removal found within search bounds.';$('action').textContent=d.action.selected||'No beneficial candidate action in this scenario.'}catch(e){$('status').textContent='Unavailable';$('error').textContent='Unable to evaluate the scenario. Try again.'}finally{btn.disabled=false}}\n$('run').addEventListener('click',run);$('file').addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;if(f.size>25*1024*1024){$('digest').textContent='Choose a file below 25 MB.';return}try{const b=await crypto.subtle.digest('SHA-256',await f.arrayBuffer());$('digest').textContent=Array.from(new Uint8Array(b),x=>x.toString(16).padStart(2,'0')).join('')}catch{$('digest').textContent='Hash calculation failed.'}});run();\n</script></body></html>"
